+        redis_rpush $fd mylist bar
+        redis_rpush $fd mylist foobar
+        redis_rpush $fd mylist foobared
+        redis_rpush $fd mylist zap
+        redis_rpush $fd mylist bar
+        redis_rpush $fd mylist test
+        redis_rpush $fd mylist foo
